# ============================================

IMAGE_EXTENSIONS = {".png", ".jpg", ".jpeg", ".webp", ".bmp", ".tif", ".tiff"}


def list_images(image_dir: Path, recursive: bool) -> List[Path]:
    if not image_dir.is_dir():
        raise FileNotFoundError(f"图片目录不存在: {image_dir}")

    pattern_iter = image_dir.rglob("*") if recursive else image_dir.iterdir()
    images = [
        p for p in pattern_iter if p.is_file() and p.suffix.lower() in IMAGE_EXTENSIONS
    ]
    return sorted(images, key=lambda p: str(p).lower())


def assign_prompts(total: int, prompts: List[str]) -> List[str]:
    """把 total 张图平均分成 len(prompts) 份，返回每张图对应的 prompt。

    不能整除时，多出的图片依次分给前面的组（每组最多相差 1 张）。
    """
    if not prompts:
        raise ValueError("PROMPTS 不能为空，至少填一个 prompt")

    n = len(prompts)
    base, extra = divmod(total, n)
    assigned: List[str] = []
    for group_idx, prompt in enumerate(prompts):
        count = base + (1 if group_idx < extra else 0)
        assigned.extend([prompt] * count)
    return assigned


def build_rows(images: List[Path], id_mode: str, prompts: List[str]) -> List[Dict[str, Any]]:
    assigned = assign_prompts(len(images), prompts)
    rows: List[Dict[str, Any]] = []
    for i, (img, prompt) in enumerate(zip(images, assigned), 1):
        row_id = img.stem if id_mode == "stem" else f"{i:04d}"
        rows.append(
            {
                "id": row_id,
                "image_path": str(img),
                "prompt": prompt,
            }
        )
    return rows


def write_jsonl(path: Path, rows: List[Dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")


def main() -> None:
    image_dir = Path(IMAGE_DIR)
    output_jsonl = Path(OUTPUT_JSONL)

    print(f"图片目录: {image_dir}")

    images = list_images(image_dir, RECURSIVE)
    if not images:
        print(f"目录下未找到图片: {image_dir}")
        return

    rows = build_rows(images, ID_MODE, PROMPTS)
    write_jsonl(output_jsonl, rows)

    print("=" * 48)
    print("JSONL 生成完成")
    print(f"图片数量: {len(images)}")
    print(f"prompt 数量: {len(PROMPTS)}")
    counts: Dict[str, int] = {}
    for row in rows:
        counts[row["prompt"]] = counts.get(row["prompt"], 0) + 1
    for idx, p in enumerate(PROMPTS, 1):
        preview = p if len(p) <= 30 else p[:30] + "..."
        print(f"  第 {idx} 组: {counts.get(p, 0)} 张  ({preview})")
    print(f"输出文件: {output_jsonl}")
    print("=" * 48)


if __name__ == "__main__":
    main()
